import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry dynamic inputSchema validation', () => {
  // @spec specs/hal-engine-tool-input-validation/spec.md#1
  it('reports a nested required property path in dot notation', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'nested_tool',
        description: 'Validates a nested property',
        inputSchema: {
          type: 'object',
          properties: {profile: {type: 'object', properties: {token: {type: 'string'}}, required: ['token']}},
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('nested_tool', {profile: {}});

    expect(response.result).toMatch(/profile\.token.*required/i);
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#1
  it('rejects a missing required property without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register(
      () => ({
        name: 'dynamic_weather',
        description: 'Requires a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      }),
      execute
    );

    const response = await registry.execute('dynamic_weather', {});
    const executorCallCount = execute.mock.calls.length;

    expect({result: response.result, executorCallCount}).toEqual({
      result: expect.stringMatching(/location.*required/i),
      executorCallCount: 0,
    });
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#2
  it('rejects a nested wrong-typed property without leaking its value', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'found');
    registry.register(
      {
        name: 'token_lookup',
        description: 'Looks up a record by token',
        inputSchema: {
          type: 'object',
          properties: {profile: {type: 'object', properties: {token: {type: 'string'}}}},
        },
      },
      execute
    );

    const emittedLogs: string[] = [];
    const logOutput = jest.spyOn(console, 'log').mockImplementation(line => {
      emittedLogs.push(String(line));
    });
    const response = await registry.execute('token_lookup', {profile: {token: 981230}});
    logOutput.mockRestore();
    const executorCallCount = execute.mock.calls.length;

    expect({
      mentionsField: response.result.includes('profile.token'),
      mentionsExpectedType: response.result.includes('string'),
      leaksValueInResult: response.result.includes('981230'),
      leaksValueInLogs: emittedLogs.some(line => line.includes('981230')),
      executorCallCount,
    }).toEqual({
      mentionsField: true,
      mentionsExpectedType: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
      executorCallCount: 0,
    });
  });

  // @spec specs/hal-engine-tool-input-validation/spec.md#7
  it('validates each function supplied definition against its current schema', async () => {
    const registry = new ToolRegistry();
    const inputs: Array<Record<string, unknown>> = [];
    let definitionCalls = 0;
    registry.register(
      () => {
        definitionCalls += 1;
        return definitionCalls <= 2
          ? {
              name: 'dynamic_tool',
              description: 'Uses a changing schema',
              inputSchema: {
                type: 'object',
                properties: {first: {type: 'string'}},
                required: ['first'],
              },
            }
          : {
              name: 'dynamic_tool',
              description: 'Uses a changing schema',
              inputSchema: {
                type: 'object',
                properties: {second: {type: 'number'}},
                required: ['second'],
              },
            };
      },
      async input => {
        inputs.push(input);
        return 'ok';
      }
    );

    const first = await registry.execute('dynamic_tool', {first: 'ready'});
    const second = await registry.execute('dynamic_tool', {second: 2});

    expect({first: first.result, second: second.result, inputs}).toEqual({
      first: 'ok',
      second: 'ok',
      inputs: [{first: 'ready'}, {second: 2}],
    });
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [validated by rejects a missing required property without invoking the executor](../../src/orchestration/tools/registry.test.ts#L26), [validated by reports a nested required property path in dot notation](../../src/orchestration/tools/registry.test.ts#L6)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [validated by rejects a nested wrong-typed property without leaking its value](../../src/orchestration/tools/registry.test.ts#L51)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by validates each function supplied definition against its current schema](../../src/orchestration/tools/registry.test.ts#L89)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv from 'ajv';

interface SchemaError {
  keyword: string;
  dataPath?: string;
  instancePath?: string;
  params: {missingProperty?: string; type?: string};
  message?: string;
}

type SchemaValidator = ((input: unknown) => boolean) & {errors?: SchemaError[] | null};

const ajv = new Ajv({validateFormats: false, strict: false} as ConstructorParameters<typeof Ajv>[0]);

function validationFailure(name: string, validate: SchemaValidator): string {
  const reasons = (validate.errors ?? []).map(error => {
    if (error.keyword === 'required') {
      const missing = String(error.params.missingProperty);
      const path = formatErrorPath(error.instancePath ?? error.dataPath ?? '');
      return `${path ? `${path}.` : ''}${missing} is required`;
    }
    const path = formatErrorPath(error.instancePath ?? error.dataPath ?? '') || '/';
    const expected = error.params.type;
    return `${path} ${expected ? `must be ${expected}` : (error.message ?? 'is invalid')}`;
  });
  return `Invalid input for ${name}: ${reasons.join('; ')}`;
}

function formatErrorPath(path: string): string {
  return path.replace(/^\//, '').replace(/\//g, '.');
}

function compileSchema(name: string, schema: Record<string, unknown>): SchemaValidator {
  try {
    return ajv.compile(schema as never) as SchemaValidator;
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool ${name}: ${detail}`, {cause: error});
  }
}

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: SchemaValidator;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, SchemaValidator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private validatorFor(tool: StoredTool, definition: ToolDefinition): SchemaValidator {
    if (tool.validate) return tool.validate;
    const schema = definition.inputSchema;
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const validate = compileSchema(definition.name, schema);
    this.dynamicValidators.set(schema, validate);
    return validate;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: SchemaValidator | undefined;
    if (typeof definition !== 'function') {
      validate = compileSchema(resolved.name, resolved.inputSchema);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Rejects schema-invalid input as a ToolResponse; only unknown tool names throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validate = this.validatorFor(tool, definition);
    if (!validate(input)) {
      return {result: validationFailure(definition.name, validate)};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
